<script setup lang="ts">import{onMounted,ref}from'vue';import{api}from'../api';import type{Post}from'../types';const data=ref<{total:number,published:number,drafts:number,categories:Record<string,number>,recent:Post[]}>();onMounted(async()=>data.value=await api('/admin/dashboard'))</script><template><div><div class="admin-title"><div><p class="eyebrow">OVERVIEW</p><h1>仪表盘</h1></div><RouterLink class="button" to="/admin/posts/new">+ 新建文章</RouterLink></div><div v-if="data" class="stats"><article><span>文章总数</span><strong>{{data.total}}</strong></article><article><span>已发布</span><strong>{{data.published}}</strong></article><article><span>草稿</span><strong>{{data.drafts}}</strong></article><article><span>分类</span><strong>{{Object.keys(data.categories).length}}</strong></article></div><section class="panel"><h2>最近更新</h2><table><thead><tr><th>标题</th><th>状态</th><th>更新时间</th></tr></thead><tbody><tr v-for="p in data?.recent" :key="p.id"><td><RouterLink :to="`/admin/posts/${p.id}`">{{p.title}}</RouterLink></td><td><span class="badge">{{p.status==='published'?'已发布':'草稿'}}</span></td><td>{{p.updatedAt.slice(0,10)}}</td></tr></tbody></table></section></div></template>
